def max_distance_after_one_swap(n, a):
    min_index = a.index(1)
    max_index = a.index(n)

    # Calculate the initial distance
    initial_distance = abs(min_index - max_index)

    # Try swapping the minimum with the next or previous element
    if min_index > 0:
        new_distance1 = abs((min_index - 1) - max_index)
    else:
        new_distance1 = float('inf')

    if min_index < n - 1:
        new_distance2 = abs((min_index + 1) - max_index)
    else:
        new_distance2 = float('inf')

    # Try swapping the maximum with the next or previous element
    if max_index > 0:
        new_distance3 = abs((max_index - 1) - min_index)
    else:
        new_distance3 = float('inf')

    if max_index < n - 1:
        new_distance4 = abs((max_index + 1) - min_index)
    else:
        new_distance4 = float('inf')

    # Return the maximum of all possible distances
    return max(initial_distance, new_distance1, new_distance2, new_distance3, new_distance4)

# Example usage:
if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    a = list(map(int, data[1:]))
    result = max_distance_after_one_swap(n, a)
    print(result)
